import csv
from collections import Counter
import operator

def task_func(csv_file, csv_delimiter):
    counter = Counter()
    with open(csv_file, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter=csv_delimiter)
        for row in reader:
            for cell in row:
                word = cell.strip()
                if word:
                    counter[word] += 1
